source:
def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_heal(slot):
            # heal the weakest visible ally, or ourselves when no ally is visible
            if exists(weakest(allies_visible())):
                cast_at_unit(slot, weakest(allies_visible()))
            else:
                cast_self(slot)
        elif slot_is_shield(slot):
            cast_self(slot)
        elif slot_is_reset(slot):
            # resets are self-cast after a basic attack, never at an enemy
            pass
        elif slot_is_dash(slot):
            # dashes are reserved for escape and travel
            pass
        elif slot_is_aoe(slot) and slot_radius(slot) > 0:
            # area abilities hit the target tile, catching neighbours too
            cast_at_tile(slot, unit_position(u))
        else:
            cast_at_unit(slot, u)

